use std::path::Path;
fn main() {
    let args: Vec<String> = std::env::args().collect();
    let img = ndlocr_lite_rs::io::load_rgb_u8(Path::new(&args[2])).unwrap();
    let dets = ndlocr_lite_rs::infer::deim::detect_rgb_u8(Path::new(&args[1]), &img.data, img.width, img.height, 0.0).unwrap();
    let lines: Vec<_> = dets.iter().filter(|d| d.class_name.starts_with("line_")).collect();
    println!("image\t{}\t{}x{}", args[2], img.width, img.height);
    let bands = ndlocr_lite_rs::app::fallback_line_detections_from_bands(&img.data, img.width, img.height, 220, 25, 45);
    println!("fallback_bands\t{}", bands.len());
    for d in bands {println!("band\t{:?}", d.box_xyxy);}
    for threshold in [0.25_f32, 0.5, 0.75, 0.9, 0.95] {
        let accepted: Vec<_> = lines.iter().filter(|d| d.confidence > threshold).collect();
        println!("threshold\t{}\tlines\t{}\tfallback\t{}", threshold, accepted.len(), accepted.is_empty());
        if threshold == 0.9 {
            for d in accepted {println!("retained\t{}\t{}\t{:?}", d.class_name, d.confidence, d.box_xyxy);}
        }
    }
}
